fn starts_with(s: &[char], p: &[char]) -> bool {
    // Check if the prefix is empty
    if p.is_empty() {
        return true;
    }
    // Check if the sequence is shorter than the prefix
    if s.len() < p.len() {
        return false;
    }
    // Compare the characters in the sequence with the prefix
    for i in 0..p.len() {
        if s[i] != p[i] {
            return false;
        }
    }
    true
}

fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    starts_with(v, p)
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
        .filter(|seq| has_prefix(seq, &p))
        .collect()
}

// Example usage
fn main() {
    let sequences = vec![
        vec!['a', 'b', 'c'],
        vec!['a', 'b', 'd'],
        vec!['b', 'c', 'd'],
        vec!['a', 'c'],
    ];
    let prefix = vec!['a', 'b'];
    let filtered = filter_by_prefix(sequences, prefix);
    
    for seq in filtered {
        println!("{:?}", seq);
    }
}